import fs from 'fs';

const path = 'src/App.jsx';
let app = fs.readFileSync(path, 'utf8');
const start = app.indexOf('const TIPS_DATA = [');
if (start < 0) throw new Error('TIPS_DATA not found');
const end = app.indexOf('\n];', start);
if (end < 0) throw new Error('TIPS_DATA closing bracket not found');
const block = app.slice(start, end);

const categories = ['dog','cat','health','life','food','training','safety','grooming'];
const ids = [...block.matchAll(/id:\s*"t(\d+)"/g)].map(m => Number(m[1]));
const cats = [...block.matchAll(/category:\s*"(dog|cat|health|life|food|training|safety|grooming)"/g)].map(m => m[1]);
const titles = new Set([...block.matchAll(/title:\s*\{\s*ko:\s*"([^"]+)"/g)].map(m => m[1]));
const counts = Object.fromEntries(categories.map(c => [c, cats.filter(x => x === c).length]));
if (!ids.length || categories.some(c => !counts[c])) throw new Error(`Invalid PetInfo inventory: ${JSON.stringify(counts)}`);
const maxId = Math.max(...ids);
if (maxId < 274) throw new Error(`Expected dataset through at least t274, found t${maxId}.`);

const candidates = [
  {category:'dog',featured:true,titleKo:'산책 전에는 목줄과 하네스의 마모 상태를 확인해요',titleEn:'Check leash and harness wear before walks',summaryKo:'버클과 봉제선, 연결 고리가 느슨하거나 닳지 않았는지 짧게 확인해요.',summaryEn:'Briefly check buckles, stitching, and attachment points for wear or looseness.',bodyKo:'산책 전 하네스와 목줄, 리드줄의 봉제선과 금속 고리, 버클을 살펴보고 풀림이나 균열이 있으면 사용을 멈추세요. 몸에 맞는 크기도 함께 확인해 갑작스러운 이탈을 예방하세요.',bodyEn:'Before walks, inspect stitching, clips, rings, and buckles. Stop using damaged gear and confirm the fit is secure to reduce the chance of escape.'},
  {category:'dog',featured:false,titleKo:'더운 날 산책은 바닥 온도도 함께 확인해요',titleEn:'Check ground temperature on hot days',summaryKo:'기온뿐 아니라 아스팔트와 보도블록의 열기도 발바닥에 부담이 될 수 있어요.',summaryEn:'Hot pavement can stress paw pads even when the air temperature seems manageable.',bodyKo:'햇볕이 강한 날에는 손등으로 바닥 열기를 짧게 확인하고 뜨겁다면 그늘진 시간대나 잔디길을 선택하세요. 발바닥이 붉거나 벗겨진 경우에는 산책을 쉬고 수의사에게 상담하세요.',bodyEn:'On sunny days, briefly assess surface heat and choose cooler times or shaded routes if pavement is hot. Red or damaged paw pads warrant rest and veterinary advice.'},
  {category:'cat',featured:true,titleKo:'고양이 물그릇은 화장실과 거리를 두고 배치해요',titleEn:'Place cat water away from the litter box',summaryKo:'물과 화장실 공간을 분리하면 더 편안하게 이용하는 데 도움이 될 수 있어요.',summaryEn:'Separating water from the litter area can make drinking more comfortable for many cats.',bodyKo:'물그릇은 조용하고 접근하기 쉬운 곳에 두고 화장실 바로 옆은 피하세요. 여러 마리가 함께 살면 물그릇을 여러 장소에 나눠 두는 것도 도움이 됩니다.',bodyEn:'Place water in a quiet, accessible area away from the litter box. In multi-cat homes, several water stations can reduce competition.'},
  {category:'cat',featured:false,titleKo:'박스와 숨숨집은 출구가 막히지 않게 배치해요',titleEn:'Keep hideaway exits clear',summaryKo:'숨는 공간은 편안해야 하지만 다른 동물이나 가구 때문에 출구가 막히지 않아야 해요.',summaryEn:'Hideaways should feel secure without having exits blocked by furniture or other pets.',bodyKo:'고양이가 자주 사용하는 박스나 숨숨집 앞을 물건으로 막지 말고 쉽게 드나들 수 있게 유지하세요. 여러 마리가 함께 산다면 한 곳에 몰리지 않도록 숨을 공간을 분산해 주세요.',bodyEn:'Keep entrances to favorite boxes and hideaways unobstructed. In multi-cat homes, distribute hiding places so one cat cannot control access to all of them.'},
  {category:'health',featured:true,titleKo:'평소 물 마시는 양의 변화를 관찰해요',titleEn:'Watch for changes in drinking habits',summaryKo:'갑자기 물을 훨씬 많이 마시거나 거의 마시지 않는 변화는 기록해두는 것이 좋아요.',summaryEn:'A noticeable increase or decrease in drinking is worth tracking.',bodyKo:'정확한 양을 재기 어렵더라도 물그릇을 채우는 빈도와 소변량의 변화를 함께 관찰하세요. 갑작스럽고 지속적인 변화가 있거나 다른 증상이 동반되면 수의사에게 상담하세요.',bodyEn:'Even without exact measurements, note how often bowls need refilling and whether urination changes. Persistent or sudden changes, especially with other symptoms, should be discussed with a veterinarian.'},
  {category:'health',featured:false,titleKo:'약을 먹인 뒤 이상 반응이 있으면 시간과 증상을 기록해요',titleEn:'Record timing and symptoms after medication reactions',summaryKo:'약 복용 뒤 구토나 심한 처짐 등 이상이 보이면 언제 시작됐는지 기록해요.',summaryEn:'If unusual signs appear after medication, note when they began and what happened.',bodyKo:'복용한 약 이름과 시간, 용량, 이후 나타난 증상을 기록해 담당 동물병원에 전달하세요. 호흡곤란, 의식 저하, 심한 붓기처럼 위급해 보이는 증상은 즉시 진료를 받아야 합니다.',bodyEn:'Record the medicine, dose, time given, and subsequent signs for the veterinary team. Breathing difficulty, collapse, or severe swelling requires urgent veterinary care.'},
  {category:'life',featured:true,titleKo:'손님이 오는 날에는 반려동물이 쉴 조용한 공간을 마련해요',titleEn:'Provide a quiet retreat when guests visit',summaryKo:'낯선 사람과 소음이 부담스러운 반려동물에게는 스스로 물러날 수 있는 공간이 필요해요.',summaryEn:'Pets overwhelmed by visitors benefit from having a place to retreat on their own.',bodyKo:'익숙한 침구와 물을 둔 조용한 공간을 준비하고 억지로 손님과 인사시키지 마세요. 반려동물이 편안할 때 스스로 접근하도록 두고 출입문 관리에도 주의하세요.',bodyEn:'Prepare a quiet area with familiar bedding and water. Do not force greetings; allow the pet to approach voluntarily and manage exterior doors carefully.'},
  {category:'life',featured:false,titleKo:'외출이 길어질 때는 급수 상태를 다시 확인해요',titleEn:'Recheck water access before longer absences',summaryKo:'평소보다 오래 집을 비운다면 깨끗한 물이 충분한지 한 번 더 확인해요.',summaryEn:'Before a longer-than-usual absence, confirm there is enough clean water available.',bodyKo:'물그릇이 쉽게 엎어지지 않는지와 급수기 작동 여부를 확인하고 필요한 경우 물 공급 지점을 두 곳 이상 마련하세요. 장시간 혼자 두는 일정은 반려동물의 나이와 건강 상태에 맞게 조정하세요.',bodyEn:'Check that bowls cannot easily tip and that fountains are working. Consider more than one water source and tailor time alone to the pet’s age and health.'},
  {category:'food',featured:true,titleKo:'사료 계량컵은 같은 기준으로 사용해요',titleEn:'Use a consistent method to measure food',summaryKo:'매번 다른 컵이나 눈대중 대신 같은 계량 기준을 쓰면 급여량 관리가 쉬워요.',summaryEn:'Using the same measuring method makes portion tracking more reliable.',bodyKo:'가능하면 주방저울을 사용하고, 계량컵을 쓴다면 같은 컵과 눈금을 유지하세요. 체중이나 몸 상태가 달라지면 임의로 크게 조절하기보다 수의사와 적정 급여량을 상의하세요.',bodyEn:'A kitchen scale is most precise, but if you use a cup, use the same one consistently. Significant portion changes should be discussed with a veterinarian when weight or body condition changes.'},
  {category:'food',featured:false,titleKo:'냉장 보관한 습식사료는 너무 차갑지 않게 급여해요',titleEn:'Avoid serving refrigerated wet food ice-cold',summaryKo:'냉장 보관한 음식은 제품 안내를 지키면서 너무 차갑지 않게 제공해요.',summaryEn:'Follow storage directions and avoid serving refrigerated wet food extremely cold.',bodyKo:'먹을 만큼만 덜어 잠시 두거나 안전하게 미지근한 온도로 맞춘 뒤 급여하세요. 상온에 오래 방치하지 말고 남은 음식의 보관 시간은 제품 안내를 따르세요.',bodyEn:'Portion out only what will be served and let it warm slightly if appropriate. Do not leave food out for extended periods and follow the manufacturer’s storage guidance.'},
  {category:'training',featured:true,titleKo:'짧은 훈련은 성공한 순간에 끝내요',titleEn:'End short training sessions on a success',summaryKo:'오래 반복하기보다 몇 번의 쉬운 성공 뒤 마무리하면 집중을 유지하기 좋아요.',summaryEn:'A few easy successes can be better than stretching a session until focus is lost.',bodyKo:'한 번에 길게 반복하기보다 1~3분 정도의 짧은 연습을 여러 번 나누고 잘한 행동 뒤 마무리하세요. 반려동물이 피곤하거나 스트레스를 보이면 즉시 쉬게 해주세요.',bodyEn:'Use brief sessions of a few minutes and stop after a successful repetition. If the pet appears tired or stressed, give them a break.'},
  {category:'training',featured:false,titleKo:'실내에서 리드줄을 착용하는 연습부터 해요',titleEn:'Practice wearing the leash indoors first',summaryKo:'산책이 익숙하지 않은 반려동물은 조용한 실내에서 장비에 적응하는 시간을 가져요.',summaryEn:'Pets new to walking can first become comfortable with leash equipment indoors.',bodyKo:'짧은 시간 하네스와 리드줄을 착용하고 편안하게 움직이면 칭찬과 보상을 주세요. 불편해하거나 물어뜯으려 하면 시간을 줄이고 천천히 적응시키세요.',bodyEn:'Let the pet wear the harness and leash briefly indoors and reward calm movement. If they seem uncomfortable, shorten the session and build up gradually.'},
  {category:'safety',featured:true,titleKo:'현관문 근처에는 반려동물 이탈 방지 루틴을 만들어요',titleEn:'Create an escape-prevention routine at the front door',summaryKo:'택배나 손님 응대 때 반려동물이 문밖으로 나가지 않도록 미리 동선을 정해요.',summaryEn:'A planned doorway routine can reduce escape risk during deliveries and visitors.',bodyKo:'문을 열기 전 반려동물을 안전한 위치로 이동시키거나 게이트를 활용하세요. 가족 구성원 모두가 같은 방식으로 현관문을 관리하면 실수를 줄일 수 있습니다.',bodyEn:'Before opening the door, move the pet to a secure area or use a gate. A consistent household routine reduces accidental escapes.'},
  {category:'safety',featured:false,titleKo:'작은 자석과 배터리는 반려동물 손이 닿지 않게 보관해요',titleEn:'Keep small magnets and batteries out of reach',summaryKo:'단추형 배터리와 작은 자석은 삼키면 매우 위험할 수 있어요.',summaryEn:'Button batteries and small magnets can be very dangerous if swallowed.',bodyKo:'리모컨과 장난감, 전자기기의 배터리 덮개가 잘 닫혀 있는지 확인하고 여분의 배터리와 자석은 잠금 가능한 곳에 보관하세요. 삼킨 가능성이 있다면 즉시 동물병원에 연락하세요.',bodyEn:'Check battery compartments on remotes and toys and store spare batteries and magnets securely. If ingestion is possible, contact a veterinarian immediately.'},
  {category:'grooming',featured:true,titleKo:'빗질은 털 끝부터 조금씩 풀어가요',titleEn:'Work through tangles gradually from the ends',summaryKo:'엉킨 털을 뿌리부터 세게 당기기보다 끝부분부터 나눠 풀어줘요.',summaryEn:'Work from the ends of tangles rather than pulling hard from the roots.',bodyKo:'털을 작은 구역으로 나눠 피부를 잡아당기지 않게 부드럽게 빗으세요. 심하게 엉킨 털은 무리하게 자르거나 뜯지 말고 전문 미용사나 수의사에게 도움을 요청하세요.',bodyEn:'Work in small sections and avoid pulling on the skin. Severe mats should not be ripped or cut blindly; seek help from a groomer or veterinarian.'},
  {category:'grooming',featured:false,titleKo:'목욕 전에는 귀와 피부 상태를 먼저 확인해요',titleEn:'Check ears and skin before bathing',summaryKo:'붉음이나 상처가 있는지 먼저 보면 목욕 중 자극을 줄이는 데 도움이 돼요.',summaryEn:'A quick pre-bath skin and ear check can help avoid aggravating sore areas.',bodyKo:'피부가 심하게 붉거나 상처, 진물, 악취가 있다면 목욕 제품을 사용하기 전에 상태를 확인받는 것이 좋아요. 귀 안쪽에 물이 들어가지 않도록 주의하고 목욕 뒤에는 충분히 말려주세요.',bodyEn:'If there is marked redness, wounds, discharge, or odor, consider veterinary advice before bathing. Keep water out of the ear canals and dry the coat thoroughly afterward.'}
];

const fresh = candidates.filter(item => !titles.has(item.titleKo));
if (fresh.length !== 16) throw new Error(`Expected 16 unique PetInfo candidates, found ${fresh.length}`);

let nextId = maxId + 1;
const lines = fresh.map(item => `  { id: "t${nextId++}", category: "${item.category}", featured: ${item.featured},\n    title: { ko: ${JSON.stringify(item.titleKo)}, en: ${JSON.stringify(item.titleEn)} },\n    summary: { ko: ${JSON.stringify(item.summaryKo)}, en: ${JSON.stringify(item.summaryEn)} },\n    body: { ko: ${JSON.stringify(item.bodyKo)}, en: ${JSON.stringify(item.bodyEn)} }, sourceDate: "2026-08-24" },`).join('\n');

app = app.slice(0, end) + '\n\n' + lines + app.slice(end);
fs.writeFileSync(path, app);
console.log(`Added ${fresh.length} PetInfo items through t${nextId - 1}`);
